def answers(repo: Path) -> dict:
    """The flattened docs/setup.md frontmatter; {} when there is no answer home (nothing landed)."""
    p = repo / SETUP_MD
    if not p.is_file():
        return {}
    m = FM_RE.match(p.read_text(encoding="utf-8", errors="replace"))
    if not m:
        raise GateFault(f"{SETUP_MD} has no readable frontmatter — the answers live there")
    data = parse_yaml(m.group(1))
    if not isinstance(data, dict):
        raise GateFault(f"{SETUP_MD} frontmatter is not a mapping")
    out, stack = {}, [("", data)]
    while stack:
        pre, node = stack.pop()
        for k, v in node.items():
            if isinstance(v, dict) and v:
                stack.append((f"{pre}{k}.", v))
            else:
                out[f"{pre}{k}"] = v
    return out


# ─── text ──────────────────────────────────────────────────────────────────────

STRINGS = {   # the language's string literals, kept whole by mask: single-line, except a backtick or a triple quote
    "sql": (r"'(?:[^'\n]|'')*'", r'"[^"\n]*"', r"\$(?P<dq>(?:[A-Za-z_]\w*)?)\$[\s\S]*?\$(?P=dq)\$"),   # PostgreSQL $$…$$ / $t$…$t$
    "py": (r'[rRbBuU]*"""[\s\S]*?"""', r"[rRbBuU]*'''[\s\S]*?'''", r'"(?:[^"\\\n]|\\.)*"', r"'(?:[^'\\\n]|\\.)*'"),
    "xml": (r"<!\[CDATA\[[\s\S]*?\]\]>",),
    "c": (r"`[^`]*`", r'"(?:[^"\\\n]|\\.)*"', r"'(?:[^'\\\n]|\\.)*'"),
}


def _strings(path: str) -> tuple[str, ...]:
    ext = Path(path).suffix.lower()
    if ext == ".sql":
        return STRINGS["sql"]
    if ext in (".py", ".rb", ".exs", ".ex"):
        return STRINGS["py"]
    return STRINGS["xml"] if ext == ".xml" else () if ext in (".yaml", ".yml") else STRINGS["c"]


def _comment_style(path: str) -> tuple[tuple[str, ...], tuple[tuple[str, str], ...]]:
    """(line comment tokens, block comment pairs) of the file's language."""
    ext = Path(path).suffix.lower()
    if ext == ".sql":
        return ("--",), (("/*", "*/"),)
    if ext in (".py", ".rb", ".yaml", ".yml", ".exs", ".ex"):
        return ("#",), ()
    if ext == ".xml":
        return (), (("<!--", "-->"),)
    if ext == ".php":
        return ("//", "#"), (("/*", "*/"),)
    return ("//",), (("/*", "*/"),)


_MASKS: dict[tuple, re.Pattern] = {}


def mask(text: str, path: str) -> str:
    """Comments blanked (newlines kept), so a commented-out step is no step and a line number stays a line number; a
    string literal is kept whole — `'a--b'`, `"http://x"`, `$$/*$$`, a CDATA section hide nothing after them. A block
    comment that never closes, and MySQL's executable `/*! … */`, stay code: an opener never blanks the rest of a file."""
    style = (_comment_style(path), _strings(path))
    if style not in _MASKS:
        (lines, blocks), strs = style
        _MASKS[style] = re.compile("|".join([f"(?P<s{k}>{s})" for k, s in enumerate(strs)]
                                            + [re.escape(o) + (r"(?!!)" if strs is STRINGS["sql"] and o == "/*" else "") + r".*?" + re.escape(c) for o, c in blocks]
                                            + [re.escape(t) + r"[^\n]*" for t in lines]), re.S)
    return _MASKS[style].sub(lambda m: m.group(0) if any(v is not None for v in m.groupdict().values()) else re.sub(r"[^\n]", " ", m.group(0)), text)


def _is_comment(line: str, path: str) -> bool:
    lines, blocks = _comment_style(path)
    s = line.strip()
    return bool(s) and (any(s.startswith(t) for t in lines) or any(s.startswith(o) or s.endswith(c) or s.startswith("*") for o, c in blocks))


def up_part(text: str, adapter: dict) -> str:
    """The text with every down region blanked: from a down marker to the next up marker, or the end."""
    def blank(m: re.Match) -> str:   # the named group `r` when the pattern has one (RunSQL's reverse), else the match
        a, b = m.span("r") if "r" in m.re.groupindex else m.span()
        g, o = m.group(0), m.start()
        return g[:a - o] + re.sub(r"[^\n]", " ", g[a - o:b - o]) + g[b - o:]
    for pat in adapter.get("strip", ()):
        text = pat.sub(blank, text)
    ups = [re.compile(p, re.M) for p in adapter.get("up", ())]
    downs = [re.compile(p, re.M) for p in adapter.get("down", ())]
    if not downs:
        return text
    lines, inside = text.split("\n"), False
    for k, ln in enumerate(lines):
        if any(d.search(ln) for d in downs):
            inside = True
        elif any(u.search(ln) for u in ups):
            inside = False
        if inside:
            lines[k] = ""
    return "\n".join(lines)


def _line(text: str, pos: int) -> int:
    return text.count("\n", 0, pos)


def _tag(raw: list[str], first: int, last: int, path: str) -> str | None:
    """The decision tag (FDR or ADR) on the step's lines, or in the comment block right above its first line."""
    for k in range(first, min(last, len(raw) - 1) + 1):
        m = TAG.search(raw[k])
        if m:
            return m.group(1) or m.group(2)
    k = first - 1
    while k >= 0 and _is_comment(raw[k], path):
        m = TAG.search(raw[k])
        if m:
            return m.group(1) or m.group(2)
        k -= 1
    return None


def steps(text: str, path: str, adapter: str) -> list[dict]:
    """The destructive steps of the up part: [{line (1-based), kind, adr}]."""
    ad = ADAPTERS[adapter]
    raw = text.split("\n")
    body = mask(up_part(text, ad), path)
    found: dict[int, dict] = {}
    pats = list(SQL_DESTRUCTIVE) + ([("DSL", ad["dsl"])] if ad.get("dsl") is not None else [])
    for kind, pat in pats:
        for m in pat.finditer(body):
            first, last = _line(body, m.start() + (len(m.group(0)) - len(m.group(0).lstrip()))), _line(body, m.end())
            if first not in found:
                found[first] = {"line": first + 1, "kind": kind if kind != "DSL" else re.sub(r"^\W+|[\s(]+$", "", m.group(0)), "adr": _tag(raw, first, last, path)}
    return [found[k] for k in sorted(found)]


def _bare(name: str) -> str:
    return name.strip('"`[]').split(".")[-1].lower()


def _call(text: str, open_at: int) -> str:
    """The balanced argument list that opens at `open_at` (to the end when it never closes)."""
    depth = 0
    for k in range(open_at, len(text)):
        depth += {"(": 1, ")": -1}.get(text[k], 0)
        if depth == 0:
            return text[open_at:k + 1]
    return text[open_at:]


def index_steps(text: str, path: str, adapter: str) -> list[dict]:
    """PostgreSQL: the index steps of the up part that lock a live table (its table not created in the same file)."""
    raw = text.split("\n")
    body = mask(up_part(text, ADAPTERS[adapter]), path)
    created = {_bare(m.group(1)) for m in SQL_CREATE_TABLE.finditer(body)}
    pats = [SQL_INDEX]
    if adapter in DSL_INDEX:
        pats.append(DSL_INDEX[adapter][0])
        created |= {_bare(m.group(1)) for m in DSL_INDEX[adapter][1].finditer(body)}
    out = []
    for pat in pats:
        for m in pat.finditer(body):
            if _bare(m.group(1)) in created or (pat is not SQL_INDEX and CONCURRENT_KW.search(_call(body, body.index("(", m.start())))):
                continue
            first, last = _line(body, m.start()), _line(body, m.end())
            out.append({"line": first + 1, "table": _bare(m.group(1)), "adr": _tag(raw, first, last, path)})
    return out


# ─── the migration set ─────────────────────────────────────────────────────────

def _globs(repo: Path) -> tuple[tuple[str, ...], list[str]]:
    paths = key(repo, "data.migrations_paths")
    if paths is not None and (not isinstance(paths, list) or not all(isinstance(x, str) and x.strip() for x in paths)):
        raise GateFault("`data.migrations_paths` must be null (the known layouts) or a list of globs")
    tests = key(repo, "traceability.test_roots") or ["tests/**"]
    if not isinstance(tests, list):
        tests = ["tests/**"]
    return (tuple(paths) if paths else LAYOUTS), [t for t in tests if isinstance(t, str)]


def _match(path: str, globs) -> bool:
    return any(fnmatch.fnmatchcase(path, g) or (g.endswith("/**") and path.startswith(g[:-2])) for g in globs)


def is_migration(path: str, layouts, tests) -> bool:
    name = Path(path).name
    return (path.endswith(EXTS) and name not in SKIP_NAMES and not path.endswith(SKIP_SUFFIX)
            and _match(path, layouts) and not _match(path, tests) and "/node_modules/" not in f"/{path}")


def _is_down(path: str, adapter: str, tool: str = "") -> bool:
    """A down file, by the form its own tool gives it — `<v>_<name>.down.sql` or a folder's `down.sql` (golang-migrate,
    sqlx-cli, Diesel), a Flyway undo `U<v>__` — never by a word inside the name (`V8__revert_discount.sql` is an up), and
    never a form another tool would run as an up (Flyway runs `V3__drop.down.sql`)."""
    p = Path(path)
    return adapter == "sql" and ((tool in DOWN_FILE_TOOLS and bool(DOWN_FILE.search(p.stem)))
                                 or (tool == "Flyway" and bool(FLYWAY_UNDO.match(p.name))))


VERSION = re.compile(r"^[Vv]?(\d+(?:[._-]\d+)*)(?=[_.-]|$)")


def _unit(path: str) -> tuple[str, str | None]:
    """(the directory a version is unique in, the version token): `migration.sql` / `up.sql` / `down.sql` take their
    folder's name (Prisma, Diesel), a Flyway undo `U3__` names version 3."""
    p = Path(path)
    if p.name in ("migration.sql", "up.sql", "down.sql"):
        m = VERSION.match(p.parent.name)
        return p.parent.parent.as_posix(), m.group(1) if m else None
    m = VERSION.match(re.sub(r"^U(?=\d)", "", p.name)) if not MUTABLE.search(p.name) else None
    return p.parent.as_posix(), m.group(1) if m else None


REV = re.compile(r"^revision\s*(?::[^=\n]+)?=\s*['\"]([\w]+)['\"]", re.M)
DOWN_REV = re.compile(r"^down_revision\s*(?::[^=\n]+)?=\s*(.+)$", re.M)


def _heads(texts: dict[str, str]) -> list[str]:
    """The Alembic heads of one directory: the revisions no other revision names as its parent."""
    revs, parents = {}, set()
    for f, t in texts.items():
        r, d = REV.search(t), DOWN_REV.search(t)
        if r:
            revs[r.group(1)] = f
        if d:
            parents |= set(re.findall(r"['\"]([\w]+)['\"]", d.group(1)))
    return sorted(r for r in revs if r not in parents)


def _accepted(repo: Path, adr: str, cache: dict) -> str | None:
    """None when the decision record (FDR or ADR) exists and is accepted; else the reason."""
    if adr in cache:
        return cache[adr]
    feature, _, rid = adr.rpartition("/")
    rel = FDR_GLOB.format(feature=feature) if feature else ADR_DIR
    d = repo / rel
    hits = sorted(p for p in d.glob(f"{rid}*.md") if re.fullmatch(re.escape(rid) + r"(?:[-_].*)?\.md", p.name)) if d.is_dir() else []
    why = None
    if not hits:
        why = (f"names {adr}, and no {rel}/{rid}-*.md exists — record the decision before the step: a feature's FDR "
               f"(/blueprint --fdr, tag `FDR: <feature>/FDR-NNNN`) or a project ADR (tag `ADR: ADR-NNN`)")
    else:
        try:
            m = FM_RE.match(hits[0].read_text(encoding="utf-8", errors="replace"))
        except OSError as e:
            m, why = None, f"names {adr}, which cannot be read ({type(e).__name__})"
        try:
            fm = parse_yaml(m.group(1)) if m else {}
        except GateFault:
            fm = {}
        status = str((fm or {}).get("status", "")).strip().lower() if isinstance(fm, dict) else ""
        if status != "accepted" and why is None:
            why = f"names {adr}, which is `{status or 'without status'}` — only an accepted decision record sanctions a destructive step"
    cache[adr] = why
    return why


def migrations(repo: Path, ref: str | None, tool: str, engine: str | None) -> tuple[dict, list[dict]]:
    """(the migrations row, the classes of the new migrations)."""
    adapter = TOOLS.get(tool)
    if adapter is None:
        return {"id": "migrations", "ok": False, "problems": [f"the migration tool `{tool}` has no adapter — answer {TOOL_KEY} again from the options SETUP offers"], "note": ""}, []
    layouts, tests = _globs(repo)
    disk = tree_entries(repo)
    mine = {p: b for p, b in disk.items() if is_migration(p, layouts, tests)}
    base = {p: b for p, b in tree_entries(repo, ref).items() if is_migration(p, layouts, tests)} if ref else {}
    problems: list[str] = []
    for p in sorted(base):
        if p not in mine:
            problems.append(f"{p}: a shipped migration is gone — a shipped migration never changes; write a new one that undoes it")
        elif mine[p].split(":")[-1] != base[p].split(":")[-1] and not MUTABLE.search(Path(p).name):
            problems.append(f"{p}: a shipped migration changed — a shipped migration never changes; restore it and write a new one")
    new = sorted(p for p in mine if p not in base)
    # a file re-applied on change (`R__`, the Liquibase master) runs again whole: a changed one is judged like a new one
    rerun = sorted(p for p in base if p in mine and MUTABLE.search(Path(p).name) and mine[p].split(":")[-1] != base[p].split(":")[-1])
    classes, cache = [], {}
    units: dict[tuple[str, str], list[str]] = {}
    for p in mine:
        u, v = _unit(p)
        if v is not None:
            units.setdefault((u, v), []).append(p)
    for p in sorted(set(new) | set(rerun)):
        try:
            text = (repo / p).read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError) as e:
            problems.append(f"{p}: cannot be read as a migration ({type(e).__name__}) — the gate never skips a file it cannot read")
            continue
        down = _is_down(p, adapter, tool)
        st = [] if down else steps(text, p, adapter)
        for s in st:
            why = (f"has no decision tag (`ADR: ADR-NNN` or `FDR: <feature>/FDR-NNNN`) on its line or in the comment right above"
                   if not s["adr"] else _accepted(repo, s["adr"], cache))
            if why:
                problems.append(f"{p}:{s['line']}: {s['kind']} {why} (rules/database.md § Destructive steps)")
        if engine == "PostgreSQL" and not down:
            for s in index_steps(text, p, adapter):
                why = _accepted(repo, s["adr"], cache) if s["adr"] else "locks writes on a live table"
                if why:
                    problems.append(f"{p}:{s['line']}: an index on `{s['table']}` {why} — build it CONCURRENTLY, or tag the step with its decision record (FDR or ADR)")
        u, v = _unit(p) if adapter != "alembic" else ("", None)
        if v is not None:
            same = [q for q in units.get((u, v), []) if q != p and _is_down(q, adapter, tool) == down]
            if same:
                problems.append(f"{p}: version {v} is also {', '.join(sorted(same))} — one version, one migration; renumber the new one")
        if not down:
            classes.append({"path": p, "class": "contract" if st else "expand", "steps": st})
    if adapter == "alembic":
        dirs: dict[str, dict[str, str]] = {}
        for p in mine:
            if p.endswith(".py"):
                try:
                    dirs.setdefault(Path(p).parent.as_posix(), {})[p] = (repo / p).read_text(encoding="utf-8", errors="replace")
                except OSError:
                    continue
        for d, texts in sorted(dirs.items()):
            if any(p in new for p in texts):
                heads = _heads(texts)
                if len(heads) > 1:
                    problems.append(f"{d}: {len(heads)} heads ({', '.join(heads)}) — reconcile the ledger: a merge revision, or rebase the new one")
    note = f"{len(mine)} migration(s), {len(new)} new ({sum(c['class'] == 'contract' for c in classes)} contract)" + (
        "" if mine else " — none under the known layouts: set data.migrations_paths when they live elsewhere")
    return {"id": "migrations", "ok": not problems, "problems": problems, "note": note}, classes


# ─── one connection factory ────────────────────────────────────────────────────

def findings(text: str, path: str) -> set[str]:
    if not any(pat.search(text) for _, pat, _ in CONNECT):   # most files hold no driver call: no masking needed
        return set()
    body = mask(text, path)
    return {label for label, pat, need in CONNECT if pat.search(body) and (need is None or need.search(text))}


def _baseline_entries(text: str | None) -> list[str]:
    try:
        data = json.loads(text or "")
    except ValueError as e:
        raise GateFault(f"not valid JSON ({e})") from None
    except RecursionError:
        raise GateFault("nested too deep for the reader") from None
    v = data.get("undeclared") if isinstance(data, dict) else None
    if not isinstance(v, list) or not all(isinstance(x, str) for x in v):
        raise GateFault("it must carry `undeclared`: a list of `<path>#<driver>` strings")
    return v


def factory(repo: Path, ref: str | None, layouts, tests) -> list[dict]:
    """The factory row, and the baseline's row when there is a baseline."""
    fac = key(repo, "data.connection_factory")
    if fac is not None and (not isinstance(fac, str) or not fac.strip()):
        return [{"id": "connection factory", "ok": False, "problems": ["`data.connection_factory` must be null or the path of the one module that builds connections"], "note": ""}]
    surface = key(repo, "surface.runtime_surface") or ["src/**"]
    surface = surface if isinstance(surface, list) else ["src/**"]
    found: dict[str, set[str]] = {}
    unread: list[str] = []
    for p in sorted(tree_entries(repo)):
        if not p.endswith(CODE_EXTS) or p == fac or not _match(p, surface) or _match(p, tests) \
                or _match(p, ("scripts/gates/**",)) or is_migration(p, layouts, tests):
            continue
        try:
            hit = findings((repo / p).read_text(encoding="utf-8", errors="replace"), p)
        except OSError as e:
            unread.append(f"{p}: cannot be read ({type(e).__name__}) — the gate never skips a file it cannot read")
            continue
        if hit:
            found[p] = hit
    keys = {f"{p}#{d}" for p, ds in found.items() for d in ds}
    rows, excused = [], set()
    bpath = key(repo, "data.baseline") or DEFAULT_BASELINE
    bp = repo / str(bpath)
    if bp.is_file():
        try:
            entries = _baseline_entries(bp.read_text(encoding="utf-8", errors="replace"))
        except GateFault as e:
            return [{"id": bpath, "ok": False, "problems": [f"cannot be read as the data baseline — {e}"], "note": ""}]
        bprob = []
        if ref is not None:
            try:
                old = set(_baseline_entries(_at(repo, ref, str(bpath)))) if _at(repo, ref, str(bpath)) is not None else set()
            except GateFault:
                old = set()
            for e in sorted(set(entries) - old):
                f, _, d = e.partition("#")
                was = _at(repo, ref, f) if f and ".." not in f.split("/") else None
                if was is None or d not in findings(was, f):
                    bprob.append(f"`{e}` is new since the base — the baseline only shrinks: get the connection from the factory instead")
        bprob += [f"`{e}` is no longer found — the baseline only shrinks: remove it" for e in sorted(set(entries) - keys)]
        excused = set(entries) & keys
        rows.append({"id": str(bpath), "ok": not bprob, "problems": bprob, "note": f"{len(excused)} connection(s) older than the law still owed — the list only shrinks"})
    owed = sorted(keys - excused)
    if fac is None:
        problems = [f"{e.replace('#', ': opens a connection (')}) — declare `data.connection_factory` (the one module that builds connections) and get it there" for e in owed]
    else:
        problems = [] if (repo / fac).is_file() else [f"the connection factory `{fac}` does not exist — name the module that builds the connections"]
        problems += [f"{e.replace('#', ': opens a connection (')}) outside the factory `{fac}` — get it from the factory" for e in owed]
    problems = unread + problems
    rows.insert(0, {"id": "connection factory", "ok": not problems, "problems": problems, "owed": owed,
                    "note": f"one path to the database ({fac})" if fac else "no connection built yet — the first backend increment declares data.connection_factory"})
    return rows


# ─── seeds through the owner ───────────────────────────────────────────────────

def _operation_ids(repo: Path) -> set[str] | None:
    from .contracts import operations
    from .freeze import CONTRACT_RE, _load
    tree = repo / CONTRACTS
    if not tree.is_dir():
        return None
    out = set()
    for p in tree.rglob("*"):
        rel = p.relative_to(repo).as_posix()
        if p.is_file() and CONTRACT_RE.fullmatch(rel):
            try:
                out |= {n for n, o in operations(_load(p)).items() if o["named"]}
            except (GateFault, RecursionError):
                continue
    return out


def _inside(repo: Path, rel: str) -> bool:
    try:
        return (repo / rel).resolve().is_relative_to(repo.resolve())
    except (OSError, RuntimeError):
        return False


def seeds(repo: Path) -> dict | None:
    p = repo / REGISTRY
    if not p.is_file():
        return None
    try:
        reg = json.loads(p.read_text(encoding="utf-8"))
    except (ValueError, OSError, RecursionError) as e:
        return {"id": REGISTRY, "ok": False, "problems": [f"cannot be read as the seed registry — {type(e).__name__}"], "note": ""}
    if not isinstance(reg, dict):
        return {"id": REGISTRY, "ok": False, "problems": ["the seed registry is not an object"], "note": ""}
    problems: list[str] = []
    if reg.get("$schema") != "seed_registry_v2":
        problems.append(f"`$schema` is `{reg.get('$schema')}` — seed_registry_v2 names each entity's owner (SETUP --upgrade moves v1)")
    ents = reg.get("shared_entities")
    if ents is not None and not isinstance(ents, dict):
        problems.append("`shared_entities` is not an object — one key per entity, each with its owner")
    ents = ents if isinstance(ents, dict) else {}
    ops, scan = None, []
    seeder = reg.get("seeder")
    if ents and not (isinstance(seeder, str) and seeder.strip()):
        problems.append("no `seeder` — name the one script that seeds every entity through its owner")
    elif isinstance(seeder, str) and seeder.strip():
        (scan.append(seeder) if _inside(repo, seeder) and (repo / seeder).is_file()
         else problems.append(f"the seeder `{seeder}` does not exist"))
    for name, e in sorted(ents.items()):
        e = e if isinstance(e, dict) else {}
        own = e.get("owner")
        if not isinstance(own, dict) or not all(isinstance(own.get(k), str) and own[k].strip() for k in ("create", "delete")):
            problems.append(f"{name}: no `owner` {{module?, create, delete}} — a seed writes through the module or the API that owns the entity")
        elif own.get("module") is not None:
            mod = own["module"]
            if not isinstance(mod, str) or not _inside(repo, mod) or not (repo / mod).is_file():
                problems.append(f"{name}: the owner module `{mod}` does not exist")
            else:
                try:
                    text = (repo / mod).read_text(encoding="utf-8", errors="replace")
                except OSError as err:
                    problems.append(f"{name}: the owner module `{mod}` cannot be read ({type(err).__name__})")
                    text = None
                problems += [] if text is None else [f"{name}: `{own[k]}` is not in {mod} — name the owner's {k} function" for k in ("create", "delete")
                             if not re.search(r"\b" + re.escape(own[k]) + r"\b", text)]
        else:
            ops = _operation_ids(repo) if ops is None else ops
            problems += [f"{name}: `{own[k]}` is no operationId of {CONTRACTS} — name the owner's {k} operation" for k in ("create", "delete")
                         if not ops or own[k] not in ops]
        fx = e.get("fixture_path")
        if not isinstance(fx, str) or not fx.endswith(".json"):
            problems.append(f"{name}: the fixture `{fx}` is not .json — a fixture is data the owner receives, never SQL")
        elif not _inside(repo, fx) or not (repo / fx).is_file():
            problems.append(f"{name}: the fixture `{fx}` does not exist")
        else:
            scan.append(fx)
    for f in scan:
        try:
            text = (repo / f).read_text(encoding="utf-8", errors="replace")
        except OSError as e:
            problems.append(f"{f}: cannot be read ({type(e).__name__}) — the gate never skips a file it cannot read")
            continue
        body = mask(text, f) if not f.endswith(".json") else text
        if SQL_WRITE.search(body):
            problems.append(f"{f}: writes a table directly (`{SQL_WRITE.search(body).group(0)}`) — call the owner's create instead")
        if findings(text, f):
            problems.append(f"{f}: opens a database connection — a seed reaches the data only through the owner")
    return {"id": REGISTRY, "ok": not problems, "problems": problems, "note": f"{len(ents)} entit{'y' if len(ents) == 1 else 'ies'} seeded through their owner"}


# ─── the member ────────────────────────────────────────────────────────────────

def check(repo: Path, base: str | None = None) -> dict:
    if context(repo) == "meta":
        return {"ok": True, "na": True, "reason": "the framework repo carries no data pack", "entries": [], "migrations": []}
    ans = answers(repo)
    tool = ans.get(TOOL_KEY)
    if not isinstance(tool, str) or not tool.strip() or tool == "None":
        return {"ok": True, "na": True, "entries": [], "migrations": [],
                "reason": f"no `{TOOL_KEY}` in {SETUP_MD} — the migration pack covers PostgreSQL, MySQL and SQLite with a backend"}
    ref = _reference(repo, base) if base else None
    layouts, tests = _globs(repo)
    mig, classes = migrations(repo, ref, tool.strip(), ans.get(ENGINE_KEY))
    rows = [mig] + factory(repo, ref, layouts, tests)
    s = seeds(repo)
    if s is not None:
        rows.append(s)
    red = [r for r in rows if not r["ok"]]
    return {"ok": not red, "entries": rows, "migrations": classes,
            "reason": f"{len(red)} of {len(rows)} red" if red else f"{len(rows)} green — {tool.strip()}"}


def render(res: dict) -> str:
    if not res.get("entries"):
        return _clean(f"data: {'n/a' if res.get('na') else 'ok' if res['ok'] else 'RED'} — {res['reason']}")
    lines = [f"data: {'ok' if res['ok'] else 'RED'} — {res['reason']}"]
    for r in res["entries"]:
        lines += [f"  ✓ {r['id']}: {r['note']}"] if r["ok"] else [f"  ✗ {r['id']}: {p}" for p in r["problems"]]
    return "\n".join(_clean(ln) for ln in lines)
